From 8a386fff4caf3050e1984200e6756ac5ffbbc783 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:25:21 +0100
Subject: [PATCH] wallpapers/image: Keep the slideshow image within its
 interval

The slideshow starts again at every lock and plasmashell start, and in
random order it then picked a new image however long the interval was;
now it saves when it picked the image and keeps it within that interval.

BUG: 445215
---
 .../image/imagepackage/contents/ui/main.qml   |  3 +-
 wallpapers/image/plugin/imagebackend.cpp      | 29 ++++++++++++++++---
 wallpapers/image/plugin/imagebackend.h        |  1 +
 .../slideshowpackage/contents/config/main.xml |  4 +++
 4 files changed, 32 insertions(+), 5 deletions(-)

diff --git a/wallpapers/image/imagepackage/contents/ui/main.qml b/wallpapers/image/imagepackage/contents/ui/main.qml
index 14aac831f8..40464472da 100644
--- a/wallpapers/image/imagepackage/contents/ui/main.qml
+++ b/wallpapers/image/imagepackage/contents/ui/main.qml
@@ -97,8 +97,9 @@ WallpaperItem {
             uncheckedSlides: root.configuration.UncheckedSlides

             // Invoked from C++
-            function writeImageConfig(newImage: string) {
+            function writeImageConfig(newImage: string, changeTime: double) {
                 configMap.Image = newImage;
+                configMap.SlideChangeTime = changeTime;
             }
         }
     }
diff --git a/wallpapers/image/plugin/imagebackend.cpp b/wallpapers/image/plugin/imagebackend.cpp
index d4413791b1..370fa42260 100644
--- a/wallpapers/image/plugin/imagebackend.cpp
+++ b/wallpapers/image/plugin/imagebackend.cpp
@@ -243,7 +243,12 @@ void ImageBackend::saveCurrentWallpaper()
         return;
     }

-    QMetaObject::invokeMethod(this, "writeImageConfig", Qt::QueuedConnection, Q_ARG(QString, m_image.toString()));
+    // Also save when the image was picked, see backgroundsFound()
+    QMetaObject::invokeMethod(this,
+                              "writeImageConfig",
+                              Qt::QueuedConnection,
+                              Q_ARG(QString, m_image.toString()),
+                              Q_ARG(double, QDateTime::currentSecsSinceEpoch()));
 }

 QAbstractItemModel *ImageBackend::slideFilterModel() const
@@ -372,9 +377,21 @@ void ImageBackend::backgroundsFound()
     }

     // start slideshow
-    m_currentSlide = m_configMap.isNull() || m_slideshowMode == SortingMode::Random
-        ? -1
-        : m_slideFilterModel->indexOf(m_configMap->value(QStringLiteral("Image")).toString()) - 1;
+    const int savedSlide = m_configMap.isNull() ? -1 : m_slideFilterModel->indexOf(m_configMap->value(QStringLiteral("Image")).toString());
+    if (savedSlide >= 0 && m_delay > 0) {
+        // The wallpaper is created again when a screen is reconnected, the screen is locked, etc.
+        // Keep the saved image if the slideshow picked it in the current interval (see scheduleNextSlide())
+        const qint64 changeTime = m_configMap->value(QStringLiteral("SlideChangeTime")).toLongLong();
+        if (changeTime / m_delay == QDateTime::currentSecsSinceEpoch() / m_delay) {
+            m_currentSlide = savedSlide;
+            const QModelIndex index = m_slideFilterModel->index(m_currentSlide, 0);
+            m_image = makeWallpaperUrl(index.data(ImageRoles::SourceRole).toUrl(), index.data(ImageRoles::SelectorsRole).toStringList());
+            Q_EMIT imageChanged();
+            scheduleNextSlide();
+            return;
+        }
+    }
+    m_currentSlide = m_slideshowMode == SortingMode::Random ? -1 : savedSlide;
     nextSlide();
 }

@@ -546,7 +563,11 @@ void ImageBackend::nextSlide()
     }

     saveCurrentWallpaper();
+    scheduleNextSlide();
+}

+void ImageBackend::scheduleNextSlide()
+{
     if (m_delay > 0) {
         // Synchronize wallpaper transitions across desktops on all screens and activities
         // by updating the wallpaper in strict time intervals since UNIX epoch, defined by `m_delay`.
diff --git a/wallpapers/image/plugin/imagebackend.h b/wallpapers/image/plugin/imagebackend.h
index 9416629f85..46d3c36960 100644
--- a/wallpapers/image/plugin/imagebackend.h
+++ b/wallpapers/image/plugin/imagebackend.h
@@ -194,6 +194,7 @@ private:
     void ensureSlideshowModel();

     void saveCurrentWallpaper();
+    void scheduleNextSlide();

     bool m_ready = false;
     int m_delay = 10;
diff --git a/wallpapers/image/slideshowpackage/contents/config/main.xml b/wallpapers/image/slideshowpackage/contents/config/main.xml
index daa132cc9e..bdf26c6f6c 100644
--- a/wallpapers/image/slideshowpackage/contents/config/main.xml
+++ b/wallpapers/image/slideshowpackage/contents/config/main.xml
@@ -65,5 +65,9 @@
       <label>Force animated images to play</label>
       <default>false</default>
     </entry>
+    <entry name="SlideChangeTime" type="LongLong">
+      <label>When the slideshow picked the current image, in seconds since the epoch</label>
+      <default>0</default>
+    </entry>
   </group>
 </kcfg>
-- 
